	.byte 2, 0
	.hword song86_track0 - song86
	.hword song86_track1 - song86
song86_track0:
	tempo_2 120
	restn 120
	end
song86_track1:
	notes_advance
	program 49
	nl c3, 24, 200
	n d3
	n e3
	n f3
	n g3
	end

@ the SndConfig structure the game passes to sndInit()
	.section .snd_config, "a"
	.global sndConfig
sndConfig:
	.word sndSampleBanks
	.word sndInstBanks
	.word sndSongs
	.word sndSfxSets
	.word sndInstToSampleBank
	.word sndSongBankMaps
	.word sndSfxBankMaps
